import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid URL provided.")
    if not isinstance(database_name, str) or not database_name:
        raise ValueError("Invalid database name provided.")

    try:
        response = requests.get(webpage_url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch webpage: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0

        headers = [header.text_content().strip() for header in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = [col.text_content().strip() for col in row.xpath('.//td')]
            if cols:
                data.append(cols)

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing the HTML content: {e}")

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        row_count = len(df)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    finally:
        if conn:
            conn.close()

    return row_count

