import bs4
import requests
import re
import json
def task_func(url: str, output_path: str) -> list:
    def fetch_content(source):
        try:
            if source.startswith(('http://', 'https://')):
                response = requests.get(source)
                response.raise_for_status()
                return response.text
            else:
                with open(source, 'r') as file:
                    return file.read()
        except Exception as e:
            raise ValueError(f"Error fetching content from {source}: {e}")

    def extract_phone_numbers(text):
        pattern = r'\+?[0-9]{1,3}[-.\s]?[0-9]{1,12}'
        return re.findall(pattern, text)

    def save_to_json(data, path):
        try:
            with open(path, 'w') as file:
                json.dump(data, file)
        except Exception as e:
            raise ValueError(f"Error saving to JSON file {path}: {e}")

    try:
        content = fetch_content(url)
        soup = bs4.BeautifulSoup(content, 'html.parser')
        text = soup.get_text()
        phone_numbers = extract_phone_numbers(text)
        save_to_json(phone_numbers, output_path)
        return phone_numbers
    except Exception as e:
        raise ValueError(f"Task failed: {e}")

