import requests
import json
from bs4 import BeautifulSoup
def task_func(url: str, file_name: str = "Output.txt") -> str:
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid or empty URL provided.")
    if not isinstance(file_name, str) or not file_name:
        raise ValueError("Invalid or empty file name provided.")
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Error fetching the webpage: {e}")
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        title = soup.title.text.strip() if soup.title else None
        with open(file_name, 'a') as f:
            f.write(json.dumps({'title': title}) + '\n')
        return file_name
    except Exception as e:
        raise ValueError(f"Error processing the webpage or writing to file: {e}")
